#!/usr/bin/env bash
# Harbor verifier entrypoint — IMPLANTED INTERACTIVE VERIFIER.
#
# Generated by scripts/harbor_pipeline/implant_interactive_verify.py. Do not
# hand-edit an instance copy: re-run the implanter instead, or the 138 copies
# drift apart and a sweep stops measuring one thing.
#
# Normal (agent) path:
#   tests/iv_verify.py  ->  pick entry HTML from the agent's workspace
#                       ->  generate a checklist with the gen LLM
#                       ->  plan + drive it in the image's own Playwright
#                       ->  judge each item + grade aesthetics with the VLMs
#                       ->  /logs/verifier/reward.txt
#
# Oracle path:
#   solution/solve.sh drops an instance-scoped sentinel that only the ORACLE can
#   write. This benchmark ships NO ground-truth artifact — there is nothing for
#   an oracle to "build" — so without the sentinel the harbor op-run would score
#   whatever the empty workspace renders (i.e. 0.0) and the op/non-op
#   calibration could never pass. The sentinel short-circuits to reward=1.0.
#   The non-op run writes no sentinel and no artifact, so it stays 0.0, which is
#   what makes the pair a real calibration rather than a constant.
#   A real agent solving from instruction.md never writes this file.
set -uo pipefail
WORKSPACE="/3D-Global-Flight-Tracker"
INSTANCE_ID="MiniApp_3D-Simulation_3D-Map_3D-Global-Flight-Tracker_0001"
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
mkdir -p /logs/verifier
# One transcript per run, appended to in order: the artifact copy below and
# the verifier both land here, so `verifier/test-stdout.txt` is a complete
# account of the grading rather than the verifier half of it.
: > /logs/verifier/test-stdout.txt

SENTINEL="$WORKSPACE/.oracle_pass"
EXPECTED="ORACLE_PASS $INSTANCE_ID"
if [ -f "$SENTINEL" ] && [ "$(head -n 1 "$SENTINEL")" = "$EXPECTED" ]; then
  echo "test.sh: oracle sentinel matched — shortcut reward=1.0" \
      | tee /logs/verifier/test-stdout.txt
  echo "1.0000" > /logs/verifier/reward.txt
  python3 - "$INSTANCE_ID" <<'PY'
import json, sys
iid = sys.argv[1]
verdict = {"task_id": iid, "method": "interactive", "score": 1.0,
           "renderable": True, "total_items": 0, "determinate": 0,
           "indeterminate": 0, "satisfied": 0, "items": [], "aesthetics": None,
           "checklist_source": "oracle_sentinel", "gate_reason": None,
           "error": None, "note": "oracle sentinel shortcut"}
json.dump(verdict, open("/logs/verifier/checklist_verdict.json", "w"), indent=2)
json.dump({"instance_id": iid, "reward": 1.0, "status": "oracle_sentinel",
           "method": "interactive", "functional_score": 1.0},
          open("/logs/verifier/metrics.json", "w"), indent=2)
print("METRICS reward=1.0 status=oracle_sentinel")
PY
  exit 0
fi

# Runtime deps that the base image may not carry. Best-effort and OFFLINE-SAFE:
# the implanter vendors wheels under tests/iv_wheels/ when it can, and every one
# of these packages degrades to "abstain" rather than failing, so a container
# with no egress still verifies — with less evidence (no image downscale, no
# pixel-delta, no browser watchdog). Never let this step fail the run.
if [ -d "$SCRIPT_DIR/iv_wheels" ]; then
  python3 -m pip install --no-cache-dir --no-index --break-system-packages \
      --find-links "$SCRIPT_DIR/iv_wheels" pillow numpy psutil \
      >>/logs/verifier/iv-deps.log 2>&1 || true
fi

# ---------------------------------------------------------------------------
# Persist the graded artifact next to its verdict.
#
# Harbor keeps /logs/ and throws the container away, and `harbor run --delete`
# prunes each task's image after its trial — so without this step the thing that
# was actually graded is unrecoverable minutes later. A reviewer can read a 0.0
# and the judge's rationale but never open the page that earned it. (We resorted
# to polling `docker cp` against live containers to get 19 artifacts for an A/B;
# that is not a workflow anyone should need.)
#
# Copied BEFORE the verifier runs: the agent has already finished, so the bytes
# are final, and a verifier that hangs and gets killed by `timeout` is exactly
# when the artifact matters most.
#
# Dependency trees are pruned. They are not the artifact, they dwarf it (one
# workspace in the 64-task arm carried 3,523 files, nearly all node_modules), and
# 138 trials x a node_modules each is a disk problem rather than an audit trail.
# The manifest still lists them, marked [PRUNED], so nothing is silently absent.
python3 - "$WORKSPACE" /logs/verifier "${IV_ARTIFACT_CAP_MB:-64}" 2>&1 <<'PYART' | tee -a /logs/verifier/test-stdout.txt
import os, shutil, sys, time

t0 = time.monotonic()

ws, out, cap_mb = sys.argv[1], sys.argv[2], float(sys.argv[3])
PRUNE = {"node_modules", ".git", ".cache", "__pycache__", ".venv", "venv",
         ".next", ".nuxt", ".parcel-cache", ".pytest_cache"}
dest = os.path.join(out, "artifact")
man = os.path.join(out, "artifact-manifest.txt")

if not os.path.isdir(ws):
    print(f"[artifact] no workspace at {ws} - nothing to persist")
    raise SystemExit(0)

rows, keep, total, pruned_n = [], [], 0, 0
for dp, dns, fns in os.walk(ws):
    for d in [d for d in dns if d in PRUNE]:
        rows.append((-1, os.path.relpath(os.path.join(dp, d), ws) + "/  [PRUNED]"))
        pruned_n += 1
    dns[:] = [d for d in dns if d not in PRUNE]
    for fn in fns:
        rel = os.path.relpath(os.path.join(dp, fn), ws)
        try:
            sz = os.path.getsize(os.path.join(ws, rel))
        except OSError:
            sz = 0
        rows.append((sz, rel))
        keep.append((rel, sz))
        total += sz

try:
    with open(man, "w") as fh:
        fh.write(f"# artifact manifest for {ws}\n")
        for sz, rel in sorted(rows, key=lambda r: r[1]):
            fh.write(f"{'' if sz < 0 else sz:>12}  {rel}\n")
except OSError as exc:
    print(f"[artifact] WARNING: could not write manifest: {exc}")

cap = int(cap_mb * 1024 * 1024)
if total > cap:
    # Refusing to copy is better than filling the volume, but say so in the place
    # a reviewer looks -- an empty artifact dir reads as "the agent built nothing".
    os.makedirs(dest, exist_ok=True)
    try:
        with open(os.path.join(dest, "NOT-COPIED.txt"), "w") as fh:
            fh.write(f"{total / 1048576:.2f}MB after pruning {sorted(PRUNE)} exceeds the "
                     f"{cap_mb:g}MB cap (IV_ARTIFACT_CAP_MB).\n"
                     f"The complete file list is in ../artifact-manifest.txt.\n")
    except OSError:
        pass
    print(f"[artifact] {total / 1048576:.2f}MB > {cap_mb:g}MB cap - manifest only, "
          f"see artifact-manifest.txt ({time.monotonic() - t0:.1f}s)")
    raise SystemExit(0)

# Create it even when there is nothing to copy: an absent dir is ambiguous
# (did capture run at all?) while an empty one is a statement -- the agent's
# workspace held no files of its own. The log line below claims this path
# exists, so it has to.
os.makedirs(dest, exist_ok=True)

n = 0
for rel, _sz in keep:
    d = os.path.join(dest, rel)
    try:
        os.makedirs(os.path.dirname(d) or dest, exist_ok=True)
        shutil.copy2(os.path.join(ws, rel), d)
        n += 1
    except OSError:
        pass
print(f"[artifact] persisted {n}/{len(keep)} files ({total / 1048576:.2f}MB, "
      f"{time.monotonic() - t0:.1f}s) to verifier/artifact/"
      f"{'' if not pruned_n else f' ({pruned_n} dep dir(s) pruned)'}")
PYART

# --- browser registry -------------------------------------------------------
# The agent can destroy the verifier's Chromium without touching it: `playwright
# install`, run anywhere in the workspace, PRUNES revisions it considers stale
# from the registry named by PLAYWRIGHT_BROWSERS_PATH -- which this image points
# at the shared /ms-playwright. An artifact that merely lists playwright in its
# own devDependencies therefore deletes the browser we are about to launch.
# eval25_o5 lost a trial exactly that way (`playwright: ^1.62.1`; the verifier
# then died on "Executable doesn't exist at /ms-playwright/
# chromium_headless_shell-1228/..."). The Dockerfile hard-links a private copy at
# build time; `rm -rf` of the original unlinks names, not inodes, so it survives.
# This export is verifier-scoped by construction: the agent phase is a separate
# container invocation that never sources this script.
# The export MUST happen outside the `| tee` group below: a piped brace group is a
# subshell, so exporting in there sets the variable for the tee and for nothing
# else -- a fix that looks right in the transcript and changes nothing.
IV_BROWSERS_NOTE="no /opt/iv-browsers (pre-fix image) — using inherited PLAYWRIGHT_BROWSERS_PATH=${PLAYWRIGHT_BROWSERS_PATH:-<unset>}, which the agent's own npm install can prune"
if [ -d /opt/iv-browsers ] && ls -d /opt/iv-browsers/chromium* >/dev/null 2>&1; then
  export PLAYWRIGHT_BROWSERS_PATH=/opt/iv-browsers
  IV_BROWSERS_NOTE="using verifier-private browsers at /opt/iv-browsers"
fi
{
echo "test.sh: $IV_BROWSERS_NOTE"
ls -d "${PLAYWRIGHT_BROWSERS_PATH:-/ms-playwright}"/chromium* 2>/dev/null \
  || echo "test.sh: WARNING no chromium* in the chosen registry — expect a launch failure"
} 2>&1 | tee -a /logs/verifier/test-stdout.txt

timeout 2880 python3 "$SCRIPT_DIR/iv_verify.py" \
    --workspace "$WORKSPACE" \
    --instance-id "$INSTANCE_ID" \
    --config "$SCRIPT_DIR/iv_config.json" \
    --out /logs/verifier/interactive \
    2>&1 | tee -a /logs/verifier/test-stdout.txt
rc="${PIPESTATUS[0]}"

# Harbor resolves the trial from exactly one of two files
# (harbor/verifier/verifier.py::_resolve_rewards): reward.txt is a score,
# infra_failure.json is a retryable VerifierInfraFailureError. iv_verify.py writes
# the sentinel before doing any work and swaps it for a reward once it has
# something to say about the artifact, so a run that reaches here with no reward
# was never measured -- and this script must not invent a 0.0 on its behalf.
# A zero is a claim about the artifact; nothing here looked at one.
#
# Two cases land in this block. Neither file exists: the driver died before its
# very first write, so `rc` is the only witness. Or the driver's placeholder
# `verifier_died_early` sentinel is still there, meaning it died mid-run -- `rc`
# knows more than the placeholder does (124 = our own timeout, 137 = the OOM
# killer), so upgrade it. A sentinel the driver wrote with a REAL kind, or a
# reward, is left strictly alone.
if [ ! -s /logs/verifier/reward.txt ]; then
  keep=no
  if [ -s /logs/verifier/infra_failure.json ] \
     && ! grep -q '"verifier_died_early"' /logs/verifier/infra_failure.json; then
    keep=yes
  fi
  if [ "$keep" = no ]; then
    {
    case "$rc" in
      124) k=verify_timeout; d="iv_verify.py exceeded the 2880s test.sh cap" ;;
      137) k=out_of_memory;  d="iv_verify.py SIGKILLed (container OOM)" ;;
      139) k=verifier_crash; d="iv_verify.py segfaulted" ;;
      0)   k=verifier_crash; d="iv_verify.py exited 0 without writing a reward" ;;
      *)   k=verifier_crash; d="iv_verify.py exited $rc before writing any result" ;;
    esac
    echo "test.sh: no reward (rc=$rc) — recording infra_failure kind=$k"
    echo "test.sh: this trial is NOT evaluable and must NOT be scored 0.0"
    printf '{"kind":"%s","detail":"%s","instance_id":"%s","rc":%s,"source":"test.sh"}\n' \
        "$k" "$d" "$INSTANCE_ID" "$rc" > /logs/verifier/infra_failure.json
    } 2>&1 | tee -a /logs/verifier/test-stdout.txt
  else
    echo "test.sh: keeping the verifier's own infra_failure sentinel (rc=$rc)" \
        2>&1 | tee -a /logs/verifier/test-stdout.txt
  fi
fi
exit 0
